<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}
require_once dirname(__DIR__, 3).'/apps/brisa/lib/audio.php';
if(!str_contains(env_value('BRISA_STORAGE'),'brisa-test-'))throw new RuntimeException('Usa un directorio de pruebas nuevo cuyo nombre contenga brisa-test-.');
if(is_file(storage_dir().'/brisa.sqlite'))throw new RuntimeException('El directorio de prueba debe estar vacío.');
$checks=0;
function check(bool $ok,string $label):void{global $checks;if(!$ok)throw new RuntimeException('FAIL: '.$label);$checks++;echo "PASS: $label\n";}
function rejects(callable $fn,int $code,string $label):void{try{$fn();}catch(DomainException $e){check($e->getCode()===$code,$label);return;}throw new RuntimeException('FAIL: '.$label);}
$task=save_item('task',['title'=>'Enviar propuesta','priority'=>1,'planned_date'=>'2026-10-19','due_date'=>'2026-10-20']);
check($task['status']==='pending','Crear tarea persistente');
$moved=save_item('task',[...$task,'planned_date'=>'2026-10-21']);
check($moved['due_date']==='2026-10-20','Mover no cambia vencimiento');
rejects(fn()=>save_item('task',[...$task,'title'=>'Edición antigua']),409,'Conflicto de edición');
rejects(fn()=>save_item('task',['title'=>'','priority'=>1]),422,'Rechazar título vacío');
rejects(fn()=>save_item('task',['title'=>'X','due_date'=>'2026-02-30']),422,'Rechazar fecha inexistente');
$event=save_item('event',['title'=>'Cita','start_at'=>'2026-10-19T10:00:00+01:00','end_at'=>'2026-10-19T11:00:00+01:00']);
check($event['start_at']==='2026-10-19 09:00:00','Normalizar citas a UTC');
rejects(fn()=>save_item('event',['title'=>'Solapada','start_at'=>'2026-10-19T09:30:00Z','end_at'=>'2026-10-19T10:30:00Z']),409,'Detectar solapamiento');
rejects(fn()=>save_item('event',['title'=>'Invertida','start_at'=>'2026-10-19T12:00:00Z','end_at'=>'2026-10-19T11:00:00Z']),422,'Rechazar intervalo invertido');
$note=save_item('note',['content'=>'Llamar mañana al dentista','title'=>'Recordatorio']);
check(json_decode($note['suggestion'],true)['type']==='task','Acción con dentista es tarea');
$suggestion=suggest('Mañana tengo reunión a las 10:30','2026-10-19T23:30:00Z','Atlantic/Canary');
check($suggestion['date']==='2026-10-21'&&$suggestion['type']==='event','Resolver mañana desde fecha y zona de captura');
$converted=convert_note(['note_id'=>$note['id'],'note_version'=>$note['version'],'type'=>'task','title'=>'Llamar al dentista']);
$again=convert_note(['note_id'=>$note['id'],'note_version'=>$note['version'],'type'=>'task','title'=>'Duplicada']);
check($converted['id']===$again['id'],'Conversión idempotente');
check(row('tasks',$converted['id'])['note_id']===$note['id'],'Conservar trazabilidad de conversión');
delete_item('task',$converted['id']);
check(row('notes',$note['id'])['status']==='inbox','Recuperar nota al eliminar destino');
$voice=save_item('note',['title'=>'Nota de voz','content'=>'Temporal']);query("UPDATE notes SET content='',source='audio' WHERE id=?",[$voice['id']]);
$aid=uid();$file=$aid.'.webm';file_put_contents(storage_dir().'/'.$file,'mock audio transport');
insert_row('audios',['id'=>$aid,'note_id'=>$voice['id'],'capture_key'=>uid(),'file_key'=>$file,'mime'=>'audio/webm','bytes'=>20,'duration_ms'=>1000,'created_at'=>now_utc()]);
$result=process_audio($aid,fn($path)=>'Comprar pan mañana');
check($result['status']==='transcribed','Trabajador guarda transcripción');
check(row('notes',$voice['id'])['content']==='Comprar pan mañana','Texto editable disponible');
check(row('audios',$aid)['transcript']==='Comprar pan mañana','Original conservado');
check(process_audio($aid,fn()=>throw new RuntimeException('No debe ejecutarse'))['status']==='idle','No volver a cobrar por trabajo finalizado');
$voice2=save_item('note',['title'=>'Audio corregido','content'=>'Mis correcciones']);$aid2=uid();$file2=$aid2.'.webm';file_put_contents(storage_dir().'/'.$file2,'mock');
insert_row('audios',['id'=>$aid2,'note_id'=>$voice2['id'],'capture_key'=>uid(),'file_key'=>$file2,'mime'=>'audio/webm','bytes'=>4,'duration_ms'=>1000,'created_at'=>now_utc()]);
process_audio($aid2,fn()=>'Texto del proveedor');
check(row('notes',$voice2['id'])['content']==='Mis correcciones','Transcripción no pisa ediciones');
check(row('audios',$aid2)['transcript']==='Texto del proveedor','Original disponible aunque se editara antes');
$voice3=save_item('note',['title'=>'Fallo','content'=>'Escrito']);$aid3=uid();$file3=$aid3.'.webm';file_put_contents(storage_dir().'/'.$file3,'mock');
insert_row('audios',['id'=>$aid3,'note_id'=>$voice3['id'],'capture_key'=>uid(),'file_key'=>$file3,'mime'=>'audio/webm','bytes'=>4,'duration_ms'=>1000,'created_at'=>now_utc()]);
$r=process_audio($aid3,fn()=>throw new RuntimeException('Proveedor no disponible'));
check($r['status']==='pending'&&row('audios',$aid3)['attempts']==1,'Reintento con backoff');
check(process_audio($aid3,fn()=>'No ejecutado')['status']==='idle','Respetar fecha de reintento');
query("UPDATE audios SET attempts=2,next_attempt_at=NULL WHERE id=?",[$aid3]);process_audio($aid3,fn()=>throw new RuntimeException('Fallo final'));
check(row('audios',$aid3)['status']==='failed','Detener tras tres intentos');
query("UPDATE audios SET status='processing',lease_until='2020-01-01 00:00:00',attempts=3 WHERE id=?",[$aid3]);cleanup_audio();
check(row('audios',$aid3)['status']==='failed','Recuperar trabajador muerto en último intento');
query("UPDATE audios SET transcribed_at='2020-01-01 00:00:00' WHERE id=?",[$aid]);cleanup_audio();
check(!is_file(storage_dir().'/'.$file)&&row('notes',$voice['id'])['content']==='Comprar pan mañana','Retención elimina archivo y conserva texto');
check(is_file(storage_dir().'/'.$file3),'Retención conserva audios fallidos');
delete_item('note',$voice2['id']);check(!is_file(storage_dir().'/'.$file2),'Borrar nota elimina su audio');
check(!query('SELECT id FROM audios WHERE id=?',[$aid2])->fetchColumn(),'Borrado en cascada');
check(isset(state_data()['config']['storage_used']),'Estado completo y cuota');
echo "$checks comprobaciones superadas.\n";
